True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    horizontal = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    vertical = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != 2]
    if not pts:
        return out
    if horizontal is not None:
        top, bottom = min(r for r, c in pts), max(r for r, c in pts)
        dr = horizontal + 1 - top if horizontal < top else horizontal - 1 - bottom
        moved = [(r + dr, c, grid[r][c]) for r, c in pts]
        for r, c in pts:
            out[r][c] = bg
        for r, c, color in moved:
            if 0 <= r < h:
                out[r][c] = color
        edge = max(r for r, c, color in moved) + 1 if horizontal < top else min(r for r, c, color in moved) - 1
        if 0 <= edge < h:
            out[edge] = [8] * w
    elif vertical is not None:
        left, right = min(c for r, c in pts), max(c for r, c in pts)
        dc = vertical + 2 - left if vertical < left else vertical - 2 - right
        moved = [(r, c + dc, grid[r][c]) for r, c in pts]
        for r, c in pts:
            out[r][c] = bg
        for r, c, color in moved:
            if 0 <= c < w:
                out[r][c] = color
        edge = max(c for r, c, color in moved) if vertical < left else min(c for r, c, color in moved)
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
    return out
